CREATE TABLE states(id INTEGER PRIMARY KEY AUTOINCREMENT, country TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE songs(id INTEGER PRIMARY KEY AUTOINCREMENT, state_id INTEGER NOT NULL, title TEXT NOT NULL, theme TEXT NOT NULL, summary TEXT NOT NULL);
CREATE TABLE listings(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, description TEXT, price TEXT, contact TEXT, seller TEXT, img TEXT, img_type TEXT, status TEXT DEFAULT 'pending');
